local a={}a.REQUIRED_HOSTS=4;a.MIN_SEPARATION=1.0;a.COPLANAR_LIMIT=0.02;local function b(c,d)local e,f,g=c.x-d.x,c.y-d.y,c.z-d.z;return math.sqrt(e*e+f*f+g*g)end;local function h(i)local j={}for k,l in ipairs(i)do local m=false;for k,n in ipairs(j)do if b(l,n)<a.MIN_SEPARATION then m=true;break end end;if not m then j[#j+1]=l end end;return j end;local function o(p)local function q(c,d)return{x=c.x-d.x,y=c.y-d.y,z=c.z-d.z}end;local r,s,t=q(p[2],p[1]),q(p[3],p[1]),q(p[4],p[1])local u=math.abs(r.x*(s.y*t.z-s.z*t.y)-r.y*(s.x*t.z-s.z*t.x)+r.z*(s.x*t.y-s.y*t.x))/6;local v=0;for k,w in ipairs({r,s,t})do local x=math.sqrt(w.x*w.x+w.y*w.y+w.z*w.z)if x>v then v=x end end;if v==0 then return 0 end;return u/(v*v*v)end;function a.grade(i)local j=h(i or{})local y=#j;local z={}local A=true;if y<a.REQUIRED_HOSTS then A=false;z[#z+1]=("only %d usable host(s); need %d"):format(y,a.REQUIRED_HOSTS)elseif o(j)<a.COPLANAR_LIMIT then A=false;z[#z+1]="hosts are effectively coplanar -- the mirror cannot be resolved"end;return{usable=A,usableHosts=y,reasons=z}end;return a